const e=JSON.parse('{"key":"v-d6ad1622","path":"/posts/Interview/docker_k8s.html","title":"云原生","lang":"zh-CN","frontmatter":{"category":["面经"],"tag":["Linux面经"],"description":"云原生 k8s 什么是 Kubernetes？ Kubernetes（简称 K8s）是一个开源的容器编排平台，用于自动化容器化应用的部署、扩展和管理。Kubernetes 使得开发人员和运维人员可以高效地管理应用程序的生命周期，特别是在大规模分布式环境中。它最初由 Google 开发，并在 2014 年捐赠给 Cloud Native Computing Foundation (CNCF)，成为其主要项目之一。 Kubernetes 提供了一种声明式的配置管理方式，通过 API 和控制器来实现自动化的管理，并且能够实现容器的高可用性、可伸缩性和自我修复。它支持多种云平台（如 AWS、Azure、GCP）和本地基础设施，使得用户可以在不同环境中运行和管理容器化应用。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/posts/Interview/docker_k8s.html"}],["meta",{"property":"og:site_name","content":"Code Building"}],["meta",{"property":"og:title","content":"云原生"}],["meta",{"property":"og:description","content":"云原生 k8s 什么是 Kubernetes？ Kubernetes（简称 K8s）是一个开源的容器编排平台，用于自动化容器化应用的部署、扩展和管理。Kubernetes 使得开发人员和运维人员可以高效地管理应用程序的生命周期，特别是在大规模分布式环境中。它最初由 Google 开发，并在 2014 年捐赠给 Cloud Native Computing Foundation (CNCF)，成为其主要项目之一。 Kubernetes 提供了一种声明式的配置管理方式，通过 API 和控制器来实现自动化的管理，并且能够实现容器的高可用性、可伸缩性和自我修复。它支持多种云平台（如 AWS、Azure、GCP）和本地基础设施，使得用户可以在不同环境中运行和管理容器化应用。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-12-01T14:01:35.000Z"}],["meta",{"property":"article:tag","content":"Linux面经"}],["meta",{"property":"article:modified_time","content":"2024-12-01T14:01:35.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"云原生\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2024-12-01T14:01:35.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"k8s","slug":"k8s","link":"#k8s","children":[{"level":3,"title":"什么是 Kubernetes？","slug":"什么是-kubernetes","link":"#什么是-kubernetes","children":[]}]}],"git":{"createdTime":1726197264000,"updatedTime":1733061695000,"contributors":[{"name":"zgjsxx","email":"119160524@qq.com","commits":2}]},"readingTime":{"minutes":6.12,"words":1837},"filePathRelative":"posts/Interview/docker_k8s.md","localizedDate":"2024年9月13日","excerpt":"<h1> 云原生</h1>\\n<h2> k8s</h2>\\n<h3> 什么是 Kubernetes？</h3>\\n<p>Kubernetes（简称 K8s）是一个开源的容器编排平台，用于自动化容器化应用的部署、扩展和管理。Kubernetes 使得开发人员和运维人员可以高效地管理应用程序的生命周期，特别是在大规模分布式环境中。它最初由 Google 开发，并在 2014 年捐赠给 Cloud Native Computing Foundation (CNCF)，成为其主要项目之一。</p>\\n<p>Kubernetes 提供了一种声明式的配置管理方式，通过 API 和控制器来实现自动化的管理，并且能够实现容器的高可用性、可伸缩性和自我修复。它支持多种云平台（如 AWS、Azure、GCP）和本地基础设施，使得用户可以在不同环境中运行和管理容器化应用。</p>","autoDesc":true}');export{e as data};
